import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as a,c as n,o,ag as s,G as h}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Google Colab","description":"Run Python in the browser and use a GPU when you need one, even without a graphics card or a local environment to set up. This page takes you from your first cell to saving results into Drive, managing keys and calling the Gemini API from a notebook.","frontmatter":{"title":"Google Colab","description":"Run Python in the browser and use a GPU when you need one, even without a graphics card or a local environment to set up. This page takes you from your first cell to saving results into Drive, managing keys and calling the Gemini API from a notebook.","domain":"product","tags":["colab","notebook","gpu"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/gemini/colab.md","filePath":"products/gemini/colab.md","lastUpdated":1795764761000}'),l={name:"products/gemini/colab.md"};function r(p,i,d,k,c,g){const t=a("DocDiagram");return o(),n("div",null,[i[0]||(i[0]=s("",44)),h(t,{src:"/diagrams/google-colab-runtime.en.svg",alt:"This diagram answers two questions: where does your code actually run, and after the runtime disconnects, what is still there and what is gone? Solid lines are relationships that survive a disconnect; dashed lines are the connections and contents that disappear. On the left is the notebook interface in the browser, on your own computer. It holds the cells, the outputs, and the sidebar, and the notebook content is edited here. At the top of the middle are two persistent places: Google Drive, which holds notebook files and data files, and GitHub, which holds notebook copies and cloned repositories. The lines between the interface and Drive, and between the interface and GitHub, are solid double-headed arrows, so they survive a disconnect. Below them is the runtime virtual machine in the cloud, where the code actually runs. Its compute type can be CPU, or switch on demand to GPU or TPU, and the interface can switch the runtime type. Three things inside the runtime disappear when it disconnects, marked with dashed rose boxes: the kernel process and in-memory variables, such as variables and imported modules; the temporary disk, such as installed packages and files uploaded to the runtime; and the mount state. The connection from the interface to the runtime is dashed as well: the interface sends cell code to the runtime, and the runtime sends output back to the interface. After you authorize a mount, the runtime reads from and writes to Drive; this line is dashed because the mount is lost on a disconnect. The runtime can pull a notebook or a repository from GitHub. On the right are the files on your computer: the originals stay on your computer, while the copy uploaded to the runtime sits on the temporary disk and disappears on a disconnect. Secrets hands a key to the code in the runtime after you authorize it. This diagram leaves out Google's internal infrastructure, any specific free-tier numbers, and button or menu names that exist only in particular versions.",width:1020,lang:"en"}),i[1]||(i[1]=s("",122))])}const b=e(l,[["render",r]]);export{f as __pageData,b as default};
